{
  "claims": [
    {
      "claim": "Under an intact BBB, Evans blue—the query dye—remains intravascular: after i.v. injection in dogs no dye was detectable in brain, CSF, or brain interstitial fluid, whereas the body stained intensely. This confirms the intact barrier blocks the tetrasulfonate bis-azo dye.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 1"
      ],
      "record_ids": [
        "Record 1-1"
      ]
    },
    {
      "claim": "When the BBB is disrupted, the structurally analogous tetrasulfonate bis-azo dye trypan blue extravasates into brain in multiple independent models, including collagenase opening, lead encephalopathy, irradiation, Urokon injury, ischemia/hypoxia, post-resuscitation injury, air embolism, and serotonin-induced barrier opening. This demonstrates meaningful CNS access for this dye class once barrier integrity is compromised.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-3",
        "Record 12-4",
        "Record 12-15",
        "Record 12-17",
        "Record 12-19",
        "Record 12-22",
        "Record 12-24",
        "Record 12-27",
        "Record 12-29"
      ]
    },
    {
      "claim": "Direct Evans blue leakage is increased by approximately 2-fold in DR6 knockout mice with BBB deficits compared with wild-type controls, confirming that the query molecule itself can enter CNS tissue under disrupted-barrier conditions.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 14"
      ],
      "record_ids": [
        "Record 14-1"
      ]
    },
    {
      "claim": "Pontamine sky blue, a closely related bis-azo tetrasulfonate dye, shows marked leakage into brain during infection-induced BBB breakdown, providing additional support that this dye class gains CNS access when the barrier is disrupted.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 13"
      ],
      "record_ids": [
        "Record 13-1",
        "Record 13-2"
      ]
    },
    {
      "claim": "Some other sulfonated/polyanionic molecules—carmoisine, NXY-059, and suramin—show poor brain penetration, including under ischemic conditions for NXY-059. These are less transferable than the direct Evans blue/trypan blue disruption evidence because they lack the same albumin-bound tracer behavior and bis-azo tetrasulfonate scaffold, but they illustrate that not all highly charged sulfonates cross even with barrier compromise.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 3",
        "Molecule 10",
        "Molecule 21"
      ],
      "record_ids": [
        "Record 3-1",
        "Record 10-1",
        "Record 21-1"
      ]
    }
  ],
  "final_prediction": "pass"
}

